<script setup lang="ts">
import {ref,computed} from 'vue';import {useRouter} from 'vue-router';import {Upload,FileText,ArrowRight} from 'lucide-vue-next';import {parseImport,type ImportRow} from '@jp/importers';import {useApp} from '../store';
const app=useApp();const router=useRouter();const title=ref('');const rows=ref<ImportRow[]>([]);const error=ref('');const fileName=ref('');const reading=ref(false);const groups=computed(()=>[...new Set(rows.value.map(r=>r.lesson))].map(lesson=>({lesson,count:rows.value.filter(r=>r.lesson===lesson).length})));
async function choose(e:Event){const file=(e.target as HTMLInputElement).files?.[0];rows.value=[];error.value='';if(!file)return;reading.value=true;try{if(file.size>5*1024*1024)throw Error('文件不能超过 5 MB');const ext=file.name.split('.').pop()?.toLowerCase();if(ext!=='csv'&&ext!=='json')throw Error('请选择 CSV 或 JSON 文件');rows.value=parseImport(await file.text(),ext);fileName.value=file.name;if(!title.value)title.value=file.name.replace(/\.(csv|json)$/i,'')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{reading.value=false}}
async function confirm(){const id=await app.addBook(rows.value,title.value);if(id)router.push('/books/'+id)}
</script>
<template><section class="page-heading"><div><p class="eyebrow">MAKE IT YOURS</p><h1>带上你的日语词书</h1><p class="muted">按课次整理，让学习从你想开始的地方开始。</p></div></section><div class="import-layout"><section><label class="upload-zone"><Upload :size="30"/><strong>{{reading?'正在解析…':'选择 CSV 或 JSON 文件'}}</strong><span>UTF-8 编码 · 最大 5 MB · 最多 10000 词</span><input type="file" accept=".csv,.json" :disabled="reading||app.busy" @change="choose"/></label><div v-if="error" class="error" role="alert">{{error}}</div><form v-if="rows.length" @submit.prevent="confirm" class="preview"><div class="section-title"><h2>导入预览</h2><span>{{fileName}}</span></div><label>词书名称<input v-model="title" required maxlength="100"/></label><p>检测到 <strong>{{groups.length}} 个课次</strong>，共 <strong>{{rows.length}} 个单词</strong></p><div class="preview-lessons"><div v-for="g in groups" :key="g.lesson"><span>{{g.lesson}}</span><span>{{g.count}} 词</span></div></div><h3>单词预览</h3><div class="sample-words"><div v-for="(row,i) in rows.slice(0,5)" :key="i"><strong>{{row.term}}</strong><span>{{row.reading}}</span><span>{{row.meaning}}</span></div></div><button class="primary" :disabled="app.busy">确认导入 <ArrowRight :size="17"/></button></form></section><aside class="format-help"><FileText :size="24"/><h2>简单的格式，就可以开始</h2><p>每行一个词，用 lesson 列标明所属课次。相同课次会自动归组。</p><code>lesson,term,reading,meaning,partOfSpeech<br>第1课,約束,やくそく,约定,名词</code><p>JSON 支持相同字段的对象数组。词性、例句和音频地址为选填。</p><a href="/examples/demo.csv" download>下载 CSV 示例 ↗</a><a href="/examples/demo.json" download>下载 JSON 示例 ↗</a><a href="/examples/detailed.json" download>下载多义项示例 ↗</a><small>文件只在你的浏览器中解析，确认后才会保存。</small></aside></div></template>
